export const SITE_CSS = "/* Strona pobierania CrownLaunchera */\n:root {\n  --bg: #0a0b0f;\n  --card: #14151c;\n  --card2: #1a1b25;\n  --line: #262836;\n  --text: #f0f0f6;\n  --muted: #9195a8;\n  --gold: #f2b01e;\n  --gold-hi: #ffd24d;\n  --err: #ff6b78;\n  color-scheme: dark;\n}\n* { box-sizing: border-box; }\nhtml, body { margin: 0; min-height: 100%; }\nbody {\n  background: var(--bg);\n  color: var(--text);\n  font: 16px/1.55 'Segoe UI Variable Text', 'Segoe UI', system-ui, -apple-system, sans-serif;\n  -webkit-font-smoothing: antialiased;\n}\n.glow {\n  position: fixed;\n  inset: 0;\n  pointer-events: none;\n  background:\n    radial-gradient(600px 380px at 50% -60px, rgba(242, 176, 30, 0.22), transparent 70%),\n    radial-gradient(500px 300px at 85% 110%, rgba(242, 176, 30, 0.08), transparent 70%);\n}\n.wrap {\n  position: relative;\n  max-width: 760px;\n  margin: 0 auto;\n  padding: 28px 18px 44px;\n}\n.brand {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  font-weight: 800;\n  font-size: 19px;\n  letter-spacing: 0.2px;\n  margin-bottom: 26px;\n}\n/* logo to tło elementu, nie <img>: bez „Zapisz obraz jako…”, przeciągania i zaznaczania (/logo.png i tak oddaje się tylko jako obraz tej strony) */\n.logo {\n  flex: none;\n  display: block;\n  width: 44px;\n  height: 44px;\n  background: url(/logo.png) center / contain no-repeat;\n  image-rendering: pixelated;\n  filter: drop-shadow(0 4px 14px rgba(242, 176, 30, 0.35));\n  user-select: none;\n  -webkit-user-select: none;\n  -webkit-user-drag: none;\n  -webkit-touch-callout: none;\n  pointer-events: none;\n}\n.admin-btn {\n  margin-left: auto;\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  padding: 10px 18px;\n  border-radius: 12px;\n  background: linear-gradient(180deg, var(--gold-hi), var(--gold));\n  color: #1a1400;\n  font-size: 15px;\n  font-weight: 800;\n  text-decoration: none;\n  box-shadow: 0 8px 24px rgba(242, 176, 30, 0.28);\n  transition: transform 0.12s, filter 0.12s;\n}\n.admin-btn:hover { filter: brightness(1.06); transform: translateY(-1px); }\n\n.card {\n  background: linear-gradient(180deg, var(--card2), var(--card));\n  border: 1px solid var(--line);\n  border-radius: 20px;\n  padding: 34px 32px 30px;\n  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.03);\n}\n.eyebrow {\n  margin: 0 0 6px;\n  color: var(--gold);\n  font-size: 13px;\n  font-weight: 700;\n  letter-spacing: 0.14em;\n  text-transform: uppercase;\n}\nh1 { margin: 0 0 8px; font-size: 38px; line-height: 1.12; letter-spacing: -0.5px; }\n.gold {\n  background: linear-gradient(90deg, var(--gold-hi), var(--gold));\n  -webkit-background-clip: text;\n  background-clip: text;\n  color: transparent;\n}\n.lead { margin: 0 0 24px; color: var(--muted); font-size: 17px; }\n\nlabel { display: block; margin: 0 0 8px; font-size: 13px; font-weight: 700; color: var(--muted); text-transform: uppercase; letter-spacing: 0.06em; }\n.row { display: flex; gap: 10px; }\ninput {\n  flex: 1;\n  min-width: 0;\n  padding: 15px 16px;\n  border-radius: 12px;\n  border: 1px solid #343846;\n  background: #0b0c11;\n  color: var(--text);\n  font: 700 17px/1.2 Consolas, 'Cascadia Mono', ui-monospace, monospace;\n  letter-spacing: 1.5px;\n  transition: border-color 0.15s, box-shadow 0.15s;\n}\ninput::placeholder { color: #565a6e; font-weight: 500; }\ninput:focus { outline: none; border-color: var(--gold); box-shadow: 0 0 0 4px rgba(242, 176, 30, 0.15); }\nbutton {\n  padding: 0 24px;\n  border: 0;\n  border-radius: 12px;\n  background: linear-gradient(180deg, var(--gold-hi), var(--gold));\n  color: #1a1400;\n  font-family: inherit;\n  font-weight: 800;\n  font-size: 16px;\n  line-height: 1;\n  cursor: pointer;\n  white-space: nowrap;\n  box-shadow: 0 8px 24px rgba(242, 176, 30, 0.28);\n  transition: transform 0.12s, filter 0.12s, box-shadow 0.12s;\n}\n/* przycisk pobierania pod polem klucza, na całą szerokość karty */\n.dl { margin-top: 12px; }\n.dl button { width: 100%; padding: 15px 20px; }\nbutton:hover { filter: brightness(1.06); transform: translateY(-1px); }\nbutton:active { transform: translateY(0); }\nbutton:disabled { opacity: 0.6; cursor: progress; transform: none; }\n\n.hint { margin: 12px 2px 0; color: var(--muted); font-size: 14px; }\n.error {\n  margin: 12px 0 0;\n  padding: 11px 14px;\n  border-radius: 10px;\n  color: var(--err);\n  background: rgba(255, 107, 120, 0.09);\n  border: 1px solid rgba(255, 107, 120, 0.35);\n  font-weight: 600;\n  animation: shake 0.35s;\n}\n@keyframes shake {\n  20%, 60% { transform: translateX(-5px); }\n  40%, 80% { transform: translateX(5px); }\n}\n\n.steps {\n  list-style: none;\n  counter-reset: s;\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 12px;\n  margin: 28px 0 0;\n  padding: 22px 0 0;\n  border-top: 1px solid var(--line);\n}\n.steps li { position: relative; padding-left: 40px; counter-increment: s; }\n.steps li::before {\n  content: counter(s);\n  position: absolute;\n  left: 0;\n  top: 1px;\n  width: 28px;\n  height: 28px;\n  border-radius: 50%;\n  display: grid;\n  place-items: center;\n  background: rgba(242, 176, 30, 0.14);\n  border: 1px solid rgba(242, 176, 30, 0.45);\n  color: var(--gold-hi);\n  font-weight: 800;\n  font-size: 14px;\n}\n.steps b { display: block; line-height: 1.3; }\n.steps span { display: block; color: var(--muted); font-size: 14px; line-height: 1.35; }\n\n.features { display: grid; grid-template-columns: repeat(2, 1fr); gap: 14px; margin-top: 18px; }\n.feat {\n  display: grid;\n  grid-template-columns: 40px 1fr;\n  /* wiersze nie rozciągają się do wysokości sąsiedniego kafelka - tytuł i opis stoją razem, wyśrodkowane przy ikonie */\n  align-content: center;\n  column-gap: 12px;\n  padding: 16px 18px;\n  background: var(--card);\n  border: 1px solid var(--line);\n  border-radius: 16px;\n}\n.feat i {\n  grid-row: span 2;\n  align-self: center;\n  width: 40px;\n  height: 40px;\n  border-radius: 12px;\n  display: grid;\n  place-items: center;\n  font-style: normal;\n  font-size: 20px;\n  background: rgba(242, 176, 30, 0.1);\n}\n.feat b { line-height: 1.3; }\n.feat span { color: var(--muted); font-size: 14px; line-height: 1.4; }\n\nfooter { margin-top: 26px; text-align: center; color: #646879; font-size: 13px; }\n\n@media (max-width: 620px) {\n  .card { padding: 26px 20px 24px; border-radius: 18px; }\n  h1 { font-size: 30px; }\n  .row { flex-direction: column; }\n  button { padding: 15px 20px; }\n  .steps { grid-template-columns: 1fr; }\n  .features { grid-template-columns: 1fr; }\n}\n@media (prefers-reduced-motion: reduce) {\n  * { animation: none !important; transition: none !important; }\n}\n";
export const SITE_JS = "// Strona pobierania: tylko wygoda (formatowanie klucza, blokada przycisku). Bez tego skryptu formularz też działa.\n(() => {\n  'use strict';\n  // logo (.logo ma pointer-events: none, więc zdarzenia trafiają do rodzica): na jego polu bez menu kontekstowego i przeciągania\n  const onLogo = (e) => [...document.querySelectorAll('.logo')].some((n) => {\n    const r = n.getBoundingClientRect();\n    return e.clientX >= r.left && e.clientX <= r.right && e.clientY >= r.top && e.clientY <= r.bottom;\n  });\n  for (const type of ['contextmenu', 'dragstart']) document.addEventListener(type, (e) => { if (onLogo(e)) e.preventDefault(); });\n\n  const input = document.getElementById('key');\n  const form = document.getElementById('f');\n  if (!input || !form) return;\n\n  /** „crownabcdefgh…” albo „abcd efgh…” -> „CROWN-ABCD-EFGH-…” (maks. 16 znaków klucza). */\n  function format(raw) {\n    let s = String(raw).toUpperCase().replace(/[^A-Z0-9]/g, '');\n    if (s.startsWith('CROWN')) s = s.slice(5);\n    s = s.slice(0, 16);\n    const groups = s.match(/.{1,4}/g) || [];\n    return groups.length ? 'CROWN-' + groups.join('-') : '';\n  }\n\n  input.addEventListener('input', () => {\n    const start = input.selectionStart;\n    const before = input.value;\n    const next = format(before);\n    if (next !== before) {\n      input.value = next;\n      // kursor na końcu przy pisaniu; przy edycji w środku zostaje blisko dawnego miejsca\n      const atEnd = start === null || start >= before.length;\n      const pos = atEnd ? next.length : Math.min(start, next.length);\n      input.setSelectionRange(pos, pos);\n    }\n  });\n\n  input.addEventListener('paste', (e) => {\n    const text = (e.clipboardData || window.clipboardData)?.getData('text');\n    if (!text) return;\n    e.preventDefault();\n    input.value = format(text);\n    input.dispatchEvent(new Event('input'));\n  });\n\n  form.addEventListener('submit', (e) => {\n    input.value = format(input.value) || input.value;\n    // blokada dopiero po zbudowaniu zawartości formularza (zablokowany przycisk nie wchodzi do wysyłanych pól)\n    const button = document.getElementById('go');\n    if (button) {\n      const label = button.textContent;\n      setTimeout(() => {\n        button.disabled = true;\n        button.textContent = 'Pobieranie…';\n        // plik pobiera się jako załącznik i strona zostaje - po chwili przywracamy przycisk\n        setTimeout(() => {\n          button.disabled = false;\n          button.textContent = label;\n        }, 6000);\n      }, 0);\n    }\n  });\n})();\n";
